import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.CsGzzEsd.js";const m=JSON.parse('{"title":"Business German Plan","description":"","frontmatter":{"title":"Business German Plan"},"headers":[],"relativePath":"blogs/German/plan.md","filePath":"blogs/German/plan.md"}'),o={name:"blogs/German/plan.md"};function r(s,e,l,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="business-german-learning-plan" tabindex="-1">Business German Learning Plan <a class="header-anchor" href="#business-german-learning-plan" aria-label="Permalink to &quot;Business German Learning Plan&quot;">​</a></h1><blockquote><p><strong>Working assumption:</strong> this is a practical, non-exam goal with about <strong>4 hours per week</strong>. The first cycle runs for 24 weeks and prioritizes recurring workplace situations over broad textbook coverage.</p></blockquote><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>By the end of the cycle, comfortably:</p><ul><li>introduce your role, background, projects, and current priorities;</li><li>participate in a 30-minute meeting, ask for clarification, and summarize decisions;</li><li>write a clear email, follow-up, status update, and polite disagreement;</li><li>give a 5–7 minute presentation and answer predictable questions;</li><li>handle a short networking or interview conversation without switching to English.</li></ul><h2 id="weekly-rhythm" tabindex="-1">Weekly rhythm <a class="header-anchor" href="#weekly-rhythm" aria-label="Permalink to &quot;Weekly rhythm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Session</th><th style="text-align:right;">Time</th><th>Work</th></tr></thead><tbody><tr><td>2 input sessions</td><td style="text-align:right;">35 min each</td><td>Read or listen to workplace German; mine useful phrases, not isolated words.</td></tr><tr><td>2 output sessions</td><td style="text-align:right;">35 min each</td><td>Write an email/status note and record a spoken response.</td></tr><tr><td>1 conversation</td><td style="text-align:right;">45–60 min</td><td>Role-play the month’s workplace scenario with correction.</td></tr><tr><td>1 review</td><td style="text-align:right;">25 min</td><td>Reuse corrected phrases and update the mistake log.</td></tr></tbody></table><p>Build a <strong>phrase bank by function</strong>: opening, clarifying, agreeing, disagreeing, proposing, delaying, summarizing, and closing.</p><h2 id="_24-week-roadmap" tabindex="-1">24-week roadmap <a class="header-anchor" href="#_24-week-roadmap" aria-label="Permalink to &quot;24-week roadmap&quot;">​</a></h2><h3 id="month-1-—-professional-identity" tabindex="-1">Month 1 — Professional identity <a class="header-anchor" href="#month-1-—-professional-identity" aria-label="Permalink to &quot;Month 1 — Professional identity&quot;">​</a></h3><ul><li>Introductions, responsibilities, team structure, and career history.</li><li>Core output: a natural 90-second introduction and a written professional profile.</li><li>Grammar repair: word order, case after common prepositions, and past narration.</li></ul><h3 id="month-2-—-email-and-messaging" tabindex="-1">Month 2 — Email and messaging <a class="header-anchor" href="#month-2-—-email-and-messaging" aria-label="Permalink to &quot;Month 2 — Email and messaging&quot;">​</a></h3><ul><li>Requests, scheduling, follow-ups, attachments, deadlines, and tone.</li><li>Core output: five reusable email patterns, each adapted to a real situation.</li><li>Focus on concise sentences and polite modal forms rather than ornate formality.</li></ul><h3 id="month-3-—-meetings" tabindex="-1">Month 3 — Meetings <a class="header-anchor" href="#month-3-—-meetings" aria-label="Permalink to &quot;Month 3 — Meetings&quot;">​</a></h3><ul><li>Agenda language, turn-taking, clarification, opinion, disagreement, and decisions.</li><li>Core output: lead a 15-minute simulated meeting and send the summary afterward.</li><li>Listen for stance and action items, then paraphrase instead of translating.</li></ul><h3 id="month-4-—-projects-and-problem-solving" tabindex="-1">Month 4 — Projects and problem-solving <a class="header-anchor" href="#month-4-—-projects-and-problem-solving" aria-label="Permalink to &quot;Month 4 — Projects and problem-solving&quot;">​</a></h3><ul><li>Status, dependencies, risk, delay, trade-offs, data, and recommendations.</li><li>Core output: a weekly two-minute project update with one risk and one request.</li><li>Practice explaining charts and numbers without scripting every sentence.</li></ul><h3 id="month-5-—-presentations-and-persuasion" tabindex="-1">Month 5 — Presentations and persuasion <a class="header-anchor" href="#month-5-—-presentations-and-persuasion" aria-label="Permalink to &quot;Month 5 — Presentations and persuasion&quot;">​</a></h3><ul><li>Signposting, comparison, emphasis, evidence, questions, and objections.</li><li>Core output: a recorded 5–7 minute presentation about one portfolio project.</li><li>Repeat the presentation after feedback until delivery is stable, not memorized.</li></ul><h3 id="month-6-—-integration" tabindex="-1">Month 6 — Integration <a class="header-anchor" href="#month-6-—-integration" aria-label="Permalink to &quot;Month 6 — Integration&quot;">​</a></h3><ul><li>Networking, interviews, negotiation, and cross-cultural workplace scenarios.</li><li>Core output: one 30-minute simulation that moves from small talk to a project discussion and follow-up email.</li><li>Identify the next cycle from actual breakdowns, not a generic level checklist.</li></ul><h2 id="monthly-feedback-loop" tabindex="-1">Monthly feedback loop <a class="header-anchor" href="#monthly-feedback-loop" aria-label="Permalink to &quot;Monthly feedback loop&quot;">​</a></h2><p>At the end of each month, keep four artifacts:</p><ol><li>one corrected email;</li><li>one recorded speaking task;</li><li>a list of five recurring mistakes;</li><li>ten high-value phrases reused in more than one situation.</li></ol><p>Track <strong>successful communication</strong>, not only correctness: Did the other person understand the request, decision, risk, and next action?</p><h2 id="first-seven-days" tabindex="-1">First seven days <a class="header-anchor" href="#first-seven-days" aria-label="Permalink to &quot;First seven days&quot;">​</a></h2><ul><li>[ ] Record a two-minute professional introduction without notes.</li><li>[ ] Write one realistic work email and get it corrected.</li><li>[ ] Create the function-based phrase bank and mistake log.</li><li>[ ] Book a weekly conversation or tutor slot.</li><li>[ ] Choose one real project as the subject for the six-month speaking portfolio.</li></ul>',27)])])}const p=t(o,[["render",r]]);export{m as __pageData,p as default};
